import React, { useState } from "react";
import "./App.css";

function App() {
  const [query, setQuery] = useState("");
  const [disease, setDisease] = useState("");
  const [location, setLocation] = useState("");
  const [whatIf, setWhatIf] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleAnalyze = async () => {
    setLoading(true);
    setData(null);

    try {
      const res = await fetch("http://127.0.0.1:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent: query,
          location,
        }),
      });

      const result = await res.json();
      setData(result);
    } catch (err) {
      console.log(err);
    }

    setLoading(false);
  };

  return (
    <div className="app">

      {/* LEFT PANEL */}
      <div className="sidebar">
        <h2>Curalink X</h2>
        <p className="sub">AI Medical Research Copilot</p>

        <input
          placeholder="e.g., Parkinson's disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="filters">
          <h3>Insight Filters</h3>
          <label><input type="checkbox" defaultChecked /> Publications</label>
          <label><input type="checkbox" defaultChecked /> Clinical trials</label>
          <label><input type="checkbox" defaultChecked /> Risk analysis</label>
        </div>

        <div className="stats">
          <h3>Stats</h3>
          <p>Research papers <span>{data?.meta?.total_papers || 0}</span></p>
          <p>Clinical trials <span>{data?.meta?.total_trials || 0}</span></p>
          <p>Risk confidence <span>0%</span></p>
          <p>Pipeline time <span>~250 ms</span></p>
        </div>
      </div>

      {/* CENTER */}
      <div className="main">
        <h1>OpenAI reasoning copilot</h1>

        <div className="query-box">
          <textarea
            placeholder="Ask your medical research question..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />

          <button onClick={handleAnalyze}>
            {loading ? "Analyzing..." : "Send message"}
          </button>
        </div>

        <div className="metadata">
          <h3>Structured query metadata</h3>

          <div className="grid">
            <input placeholder="Disease" value={disease} onChange={(e)=>setDisease(e.target.value)} />
            <input placeholder="Research focus" />
            <input placeholder="Location" value={location} onChange={(e)=>setLocation(e.target.value)} />
            <input placeholder="Age" />
            <input placeholder="Gender" />
            <input placeholder="What-if treatment" value={whatIf} onChange={(e)=>setWhatIf(e.target.value)} />
          </div>
        </div>
      </div>

      {/* RIGHT PANEL */}
      <div className="right">

        <div className="card">
          <h3>Dynamic Insights</h3>
          <p>{data ? data.insights : "Live synthesis"}</p>
        </div>

        <div className="card">
          <h3>Research papers</h3>
          {data?.publications?.length ? (
            data.publications.map((p, i) => (
              <div key={i} className="item">
                <p>{p.title}</p>
              </div>
            ))
          ) : (
            <p>No publication cards available yet</p>
          )}
        </div>

        <div className="card">
          <h3>Clinical trials</h3>
          {data?.clinical_trials?.length ? (
            data.clinical_trials.map((t, i) => (
              <div key={i} className="item">
                <p>{t.title}</p>
                <span>{t.status}</span>
              </div>
            ))
          ) : (
            <p>No clinical trials matched</p>
          )}
        </div>

        <div className="card">
          <h3>Risk analysis</h3>
          <p>Risk analysis will appear after the first evidence run.</p>
        </div>

        <div className="card">
          <h3>What-if Analysis</h3>
          <input
            placeholder="e.g., Vitamin D"
            value={whatIf}
            onChange={(e) => setWhatIf(e.target.value)}
          />
          <button className="simulate">Simulate scenario</button>
        </div>

      </div>
    </div>
  );
}

export default App;
